"""Simple ingestion script for IU Xray dataset.

Usage:
    python scripts/ingest_iuxray.py --raw_dir PATH --out_dir data/processed
"""
import argparse
from pathlib import Path
import shutil
import sys

if __package__ in (None, ""):
    sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from src.data.metadata import compact_metadata_rows, write_metadata_jsonl
from src.data.processor import process_iuxray_directory


def clean_processed_output(out_dir: Path):
    """Remove only artifacts generated by ingestion in the chosen output directory."""
    image_dir = out_dir / "images"
    metadata_path = out_dir / "metadata.csv"
    metadata_jsonl_path = out_dir / "metadata.jsonl"
    if image_dir.is_dir():
        shutil.rmtree(image_dir)
    if metadata_path.is_file():
        metadata_path.unlink()
    if metadata_jsonl_path.is_file():
        metadata_jsonl_path.unlink()


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--raw_dir", required=True, help="Path to IU Xray raw data")
    parser.add_argument("--out_dir", required=True, help="Output processed directory")
    parser.add_argument("--projections_csv", required=False, help="Path to indiana_projections.csv (optional)")
    parser.add_argument("--reports_csv", required=False, help="Path to indiana_reports.csv (optional)")
    parser.add_argument("--image_size", type=int, nargs=2, metavar=("WIDTH", "HEIGHT"), help="Optional fixed output size; omit to preserve aspect ratio")
    parser.add_argument(
        "--max_long_edge",
        type=int,
        default=1024,
        help="Maximum output long edge while preserving aspect ratio; use 0 to disable",
    )
    parser.add_argument("--clean", action="store_true", help="Remove generated images and metadata in --out_dir before ingestion")
    args = parser.parse_args()

    raw_dir = Path(args.raw_dir)
    out_dir = Path(args.out_dir)
    if args.clean:
        clean_processed_output(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    proj = Path(args.projections_csv) if args.projections_csv else None
    reps = Path(args.reports_csv) if args.reports_csv else None
    image_size = tuple(args.image_size) if args.image_size else None
    max_long_edge = args.max_long_edge or None
    metadata = process_iuxray_directory(
        raw_dir,
        out_dir,
        image_size=image_size,
        max_long_edge=max_long_edge,
        projections_csv=proj,
        reports_csv=reps,
    )

    metadata_path = out_dir / "metadata.jsonl"
    compact_metadata = compact_metadata_rows(metadata)
    write_metadata_jsonl(compact_metadata, metadata_path)
    print(f"Saved {len(compact_metadata)} compact metadata rows to {metadata_path}")


if __name__ == '__main__':
    main()
